#include <bits/stdc++.h>
using namespace std;using ll=long long;using U=unsigned long long;
struct Key {ll h,q,a,g,v;bool operator==(const Key&o)const{return h==o.h&&q==o.q&&a==o.a&&g==o.g&&v==o.v;}};
struct Hash {size_t operator()(const Key&k)const{U z=0;for(ll x:{k.h,k.q,k.a,k.g,k.v}){U y=x+0x9e3779b97f4a7c15ULL;y=(y^(y>>30))*0xbf58476d1ce4e5b9ULL;y=(y^(y>>27))*0x94d049bb133111ebULL;y^=y>>31;z^=y+0x9e3779b97f4a7c15ULL+(z<<6)+(z>>2);}return z;}};
struct W {ll t;U code;int mask;};struct Entry{W first;vector<W>*other=nullptr;};
int main(int argc,char**argv){if(argc<3)return 2;int buckets=stoi(argv[2]);long total=0,totalgroups=0;int globalbest=0,unsatbest=0;
for(int bucket=0;bucket<buckets;bucket++){unordered_map<Key,Entry,Hash> fs;fs.reserve(1500000);ifstream in(argv[1]);string line;long classes=0;while(getline(in,line)){if(line.empty()||line[0]=='#')continue;istringstream is(line);U code;ll savedH;is>>code>>savedH;if(!is)continue;if((savedH/2)%buckets!=bucket)continue;classes++;
const int n=9,N=512,F=511;int adj[n]={},z=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,z++){if(code>>z&1)adj[i]|=1<<j;else adj[j]|=1<<i;}
ll en[N][n]={},st[N][n]={},h[N]={};h[0]=1;for(int s=1;s<N;s++)for(int v=0;v<n;v++)if(s>>v&1){int r=s^(1<<v);if(!r)en[s][v]=st[s][v]=1;else for(int u=0;u<n;u++)if(r>>u&1){if(adj[u]>>v&1)en[s][v]+=en[r][u];if(adj[v]>>u&1)st[s][v]+=st[r][u];}h[s]+=en[s][v];}ll H=h[F],Q=0,aw[n]={},gw[n]={},K[n][n]={};if(H!=savedH){cerr<<"H mismatch";return 3;}for(int s=0;s<N;s++){Q+=h[s]*h[F^s];for(int i=0;i<n;i++){aw[i]+=st[s][i]*h[F^s];gw[i]+=en[s][i]*h[F^s];for(int j=0;j<n;j++)K[i][j]+=en[s][i]*st[F^s][j];}}
for(int m=0;m<N;m++){ll A=0,G=0,T=0,S=0,E=0;for(int i=0;i<n;i++)if(m>>i&1){A+=aw[i];G+=gw[i];S+=st[F][i];E+=en[F][i];for(int j=0;j<n;j++)if(m>>j&1)T+=K[i][j];}for(int v=0;v<2;v++){ll t=T+S+v*E;auto [it,inserted]=fs.try_emplace(Key{H,Q,A,G,v},Entry{W{t,code,m},nullptr});if(inserted||it->second.first.t==t)continue;auto &e=it->second;if(!e.other)e.other=new vector<W>;bool found=false;for(auto &w:*e.other)if(w.t==t)found=true;if(!found)e.other->push_back({t,code,m});}}
}
int best=1,ubest=1;long multi=0;for(auto &[key,e]:fs){if(!e.other)continue;multi++;e.other->push_back(e.first);sort(e.other->begin(),e.other->end(),[](W&a,W&b){return a.t<b.t;});auto &ws=*e.other;for(size_t i=0;i<ws.size();i++){if(i&&ws[i-1].t+2==ws[i].t)continue;size_t j=i+1;while(j<ws.size()&&ws[j].t==ws[j-1].t+2)j++;int length=j-i;bool us=gcd(key.h,key.q)==1;best=max(best,length);if(us)ubest=max(ubest,length);if(length>globalbest||(us&&length>unsatbest)){globalbest=max(globalbest,length);if(us)unsatbest=max(unsatbest,length);cout<<"{\"bucket\":"<<bucket<<",\"key\":["<<key.h<<","<<key.q<<","<<key.a<<","<<key.g<<","<<key.v<<"],\"run\":"<<length<<",\"unsaturated\":"<<us<<",\"witnesses\":[";for(size_t k=i;k<j;k++)cout<<(k>i?",":"")<<"["<<ws[k].t<<","<<ws[k].code<<","<<ws[k].mask<<"]";cout<<"]}"<<endl;}}delete e.other;}
total+=classes;totalgroups+=fs.size();cerr<<"bucket "<<bucket<<" classes "<<classes<<" groups "<<fs.size()<<" multi "<<multi<<" maxrun "<<best<<" unsatmax "<<ubest<<endl;}
cerr<<"TOTAL classes "<<total<<" groups "<<totalgroups<<" maxrun "<<globalbest<<" unsatmax "<<unsatbest<<endl;
}
